function hashId(value) {
  let hash = 2166136261;
  value = String(value || '');
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

return $input.all().map((item) => {
  const j = item.json || {};
  const body = j.body || {};

  const location = String(body.location || '').trim();
  const message = String(
    body.formatted_message ||
    body.message ||
    body.text ||
    ''
  ).trim();

  const title = String(
    body.custom_title ||
    (location ? `BNN - ${location}` : 'BNN Incident')
  ).trim();

  const combined = `${title} ${location} ${message}`.toUpperCase();

  let priority = 3;

  if (/2ND ALARM|SECOND ALARM|3RD ALARM|THIRD ALARM|WORKING FIRE|MAYDAY|MCI|ENTRAPMENT|SHOOTING|STABBING/.test(combined)) {
    priority = 5;
  } else if (/FIRE|SMOKE|POLICE|EMS|MEDICAL|MVA|MVC|ACCIDENT|HAZMAT|RESCUE/.test(combined)) {
    priority = 4;
  }

  const now = new Date().toISOString();
  const sourceEventId = hashId(location + '|' + message);

  const alert = {
    schema_version: '1.0',
    alert_id: `BNN:${sourceEventId}`,
    source: 'BNN',
    source_event_id: sourceEventId,
    category: 'PUBLIC_SAFETY',
    subtype: 'INCIDENT',
    status: 'ACTIVE',
    event_action: 'NEW',
    title,
    message: message || 'BNN incident received.',
    priority,
    county: '',
    municipality: '',
    location: {
      label: location,
      address: location,
      state: '',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['bnn', 'public-safety'],
    click_url: '',
    source_url: '',
    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,
    metadata: {
      original_location: location
    }
  };

  alert.search_text = [
    alert.source, alert.category, alert.subtype,
    location, alert.title, alert.message,
    ...alert.tags
  ].filter(Boolean).join(' ');

  return { json: alert };
});
